import numpy as np
info = np.load('data/beh/Imaging_Exp_info.npy', allow_pickle=True).item()
print('All experiment types and session counts:')
total_sessions = 0
for k in sorted(info.keys()):
    v = info[k]
    if isinstance(v, np.ndarray):
        n = len(v)
    elif isinstance(v, list):
        n = len(v)
    else:
        n = 1
    total_sessions += n
    # Get unique mice
    mice = set()
    if isinstance(v, (list, np.ndarray)):
        for entry in v:
            if isinstance(entry, dict):
                mice.add(entry.get('mname', 'unknown'))
    print(f'  {k}: {n} sessions, mice: {sorted(mice)}')
print(f'\nTotal sessions across all experiment types: {total_sessions}')

# Count unique mice across all experiments
all_mice = set()
for k in info.keys():
    v = info[k]
    if isinstance(v, (list, np.ndarray)):
        for entry in v:
            if isinstance(entry, dict):
                all_mice.add(entry.get('mname', 'unknown'))
print(f'Total unique mice: {len(all_mice)}')
print(f'Mice: {sorted(all_mice)}')
