import numpy as np

# Load retinotopy data for a session
ret = np.load('data/retinotopy/TX108_2023_01_05_trans.npz', allow_pickle=True)
print('Retinotopy keys:', list(ret.keys()))
for k in ret.keys():
    v = ret[k]
    if isinstance(v, np.ndarray):
        print(f'  {k}: shape={v.shape} dtype={v.dtype}')
        if k == 'iarea':
            print(f'    unique values: {np.unique(v)}')
            for uv in np.unique(v):
                print(f'      iarea={uv}: {np.sum(v==uv)} neurons')
        elif k == 'xy_t':
            print(f'    first 3 rows: {v[:3]}')
    else:
        print(f'  {k}: type={type(v)}')

# Check neu_area_ID mapping
def neu_area_ID(iarea):
    area_name = ['V1', 'mHV', 'lHV', 'aHV']
    idx = {}
    for ar in area_name:
        if ar=='V1':
            idx[ar] = iarea==8
        elif ar=='mHV':
            idx[ar] = (iarea==0) | (iarea==1) | (iarea==2) | (iarea==9)
        elif ar=='lHV':
            idx[ar] = (iarea==5) | (iarea==6)
        elif ar=='aHV':
            idx[ar] = (iarea==3) | (iarea==4)
    return idx

iarea = ret['iarea']
idx = neu_area_ID(iarea)
print('\nBrain region counts:')
for ar in ['V1', 'mHV', 'lHV', 'aHV']:
    print(f'  {ar}: {idx[ar].sum()} neurons')
print(f'  Unassigned (iarea=-1 or 7): {np.sum((iarea==-1) | (iarea==7))} neurons')
print(f'  Total neurons: {len(iarea)}')
print(f'  Sum of assigned: {sum(idx[ar].sum() for ar in ["V1", "mHV", "lHV", "aHV"])}')

# Check neural data dimensions match
spk_data = np.load('data/spk/TX108_2023_01_05_2_neural_data.npy', allow_pickle=True).item()
total_neurons = sum(s.shape[0] for s in spk_data['spks'])
print(f'\nNeural data total neurons: {total_neurons}')
print(f'Retinotopy total neurons: {len(iarea)}')
print(f'Match: {total_neurons == len(iarea)}')
