import numpy as np
import os

# For each neural file, find which behavior file(s) contain it
info = np.load('data/beh/Imaging_Exp_info.npy', allow_pickle=True).item()

# Build mapping: session_id -> list of (exp_type, beh_key)
session_map = {}
for exp_type in info.keys():
    for entry in info[exp_type]:
        session_id = f"{entry['mname']}_{entry['datexp']}_{entry['blk']}"
        if 'stimtype' in entry:
            beh_key = f"{entry['mname']}_{entry['datexp']}_{entry['blk']}_{entry['stimtype']}"
        else:
            beh_key = session_id
        if session_id not in session_map:
            session_map[session_id] = []
        session_map[session_id].append((exp_type, beh_key, entry))

# Check: for sessions in multiple exp types, do they use different beh files?
print('Sessions in multiple experiment types:')
for sid in sorted(session_map.keys()):
    entries = session_map[sid]
    if len(entries) > 1:
        exp_types = [e[0] for e in entries]
        beh_keys = [e[1] for e in entries]
        print(f'  {sid}: exp_types={exp_types}')

# Check which behavior files exist
beh_files = [f for f in os.listdir('data/beh/') if f.startswith('Beh_') and f.endswith('.npy')]
print(f'\nBehavior files: {sorted(beh_files)}')

# For each session, check which beh files contain it
print('\n--- Checking first 5 sessions ---')
for sid in sorted(session_map.keys())[:5]:
    entries = session_map[sid]
    for exp_type, beh_key, entry in entries:
        beh_file = f'Beh_{exp_type}.npy'
        if os.path.exists(f'data/beh/{beh_file}'):
            beh_data = np.load(f'data/beh/{beh_file}', allow_pickle=True).item()
            if beh_key in beh_data:
                beh = beh_data[beh_key]
                print(f'  {sid} in {exp_type} (key={beh_key}): ntrials={beh["ntrials"]}, isRew={beh["isRew"].sum()}/{len(beh["isRew"])}')
            else:
                print(f'  {sid} in {exp_type}: key {beh_key} NOT FOUND in {beh_file}')
